my $root = '/bench/repo';
my $module = 'github.com/usememos/memos';

# --- Phase 1: parse all Go files for package, imports, declarations ---
my %file_pkg;      # file -> package name
my %file_imports;  # file -> { alias_or_pkg => import_path }
my %decls;         # key -> { file, line, name, recv, pkg_path, pkg_name, exported, kind }

sub pkg_path_from_file {
    my ($f) = @_;
    $f =~ s{^\Q$root\E/}{};
    $f =~ s{/[^/]+$}{};
    return "$module/$f";
}

sub parse_imports {
    my ($content, $file) = @_;
    my %imps;
    if ($content =~ /^package\s+(\w+)/m) {
        $file_pkg{$file} = $1;
    }
    while ($content =~ /^import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/mg) {
        my $block = $1 // '';
        my $single = $2 // '';
        my @lines = $single ? qq{"$single"} : split /\n/, $block;
        for my $line (@lines) {
            next unless $line =~ /"([^"]+)"/;
            my $path = $1;
            my $alias = basename($path);
            $alias =~ s/-/_/g;
            if ($line =~ /^\s*(\w+)\s+"/) {
                $alias = $1;
            }
            $imps{$alias} = $path;
        }
    }
    $file_imports{$file} = \%imps;
}

sub is_test_decl_name {
    my ($name) = @_;
    return 1 if $name =~ /^(Test|Benchmark|Example|Fuzz)/;
    return 0;
}

find({
    wanted => sub {
        return unless /\.go$/;
        return if /\/vendor\//;
        my $file = $File::Find::name;
        open my $fh, '<', $file or return;
        my $content = do { local $/; <$fh> };
        close $fh;
        parse_imports($content, $file);

        return unless $file =~ m{/internal/};

        my @lines = split /\n/, $content;
        for my $i (0..$#lines) {
            my $line = $lines[$i];
            next unless $line =~ /^func\s+(?:\(([^)]*)\)\s+)?([A-Za-z_]\w*)\s*\(/;
            my ($recv, $name) = ($1 // '', $2);
            next if is_test_decl_name($name);
            next if $name eq 'init';

            my $pkg_name = $file_pkg{$file};
            my $pkg_path = pkg_path_from_file($file);
            my $recv_type = '';
            if ($recv =~ /\*?\s*([A-Za-z_]\w*)\s*$/) {
                $recv_type = $1;
            }
            my $key;
            if ($recv_type) {
                $key = "$pkg_path|$recv_type.$name";
            } else {
                $key = "$pkg_path|$name";
            }
            $decls{$key} = {
                file => $file,
                line => $i + 1,
                name => $name,
                recv => $recv_type,
                pkg_path => $pkg_path,
                pkg_name => $pkg_name,
                exported => ($name =~ /^[A-Z]/),
                kind => ($recv_type ? 'method' : 'func'),
            };
        }
    },
    no_chdir => 1,
}, $root);

# --- Phase 2: index declarations by searchable patterns ---
# pkg_path -> pkg_name (from decl file)
my %path_to_pkgname;
for my $k (keys %decls) {
    $path_to_pkgname{$decls{$k}{pkg_path}} = $decls{$k}{pkg_name};
}

# name -> list of keys (may be ambiguous across packages)
my %name_to_keys;
for my $k (keys %decls) {
    my $d = $decls{$k};
    if ($d->{kind} eq 'func') {
        push @{$name_to_keys{$d->{name}}}, $k;
    } else {
        push @{$name_to_keys{$d->{name}}}, $k;  # method name
    }
}

# --- Phase 3: count call sites ---
my %call_sites;  # decl_key -> { "file:line" => 1 }

sub add_call {
    my ($key, $file, $line) = @_;
    return unless exists $decls{$key};
    # skip self-declaration line
    my $d = $decls{$key};
    return if $file eq $d->{file} && $line == $d->{line};
    $call_sites{$key}{"$file:$line"} = 1;
}

find({
    wanted => sub {
        return unless /\.go$/;
        return if /\/vendor\//;
        my $file = $File::Find::name;
        open my $fh, '<', $file or return;
        my @lines = <$fh>;
        close $fh;

        my $pkg = $file_pkg{$file} // '';
        my $imps = $file_imports{$file} // {};
        my %imp_pkgname;  # alias -> package name from import path
        for my $alias (keys %$imps) {
            my $path = $imps->{$alias};
            $imp_pkgname{$alias} = $path_to_pkgname{$path} // basename($path);
            $imp_pkgname{$alias} =~ s/-/_/g;
        }
        # also map full last segment
        for my $alias (keys %$imps) {
            my $path = $imps->{$alias};
            (my $last = $path) =~ s/.*\///;
            $last =~ s/-/_/g;
            $imp_pkgname{$last} = $imp_pkgname{$alias} unless exists $imp_pkgname{$last};
        }

        for my $i (0..$#lines) {
            my $line = $lines[$i];
            my $ln = $i + 1;
            next if $line =~ /^\s*func\s+/;  # skip func declarations

            # qualified calls: alias.Name( or pkg.Name(
            while ($line =~ /\b([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
                my ($qual, $name) = ($1, $2);
                next if $qual eq 'http' || $qual eq 'json' || $qual eq 'fmt' || $qual eq 'strings' || $qual eq 'time' || $qual eq 'context';
                my $path = $imps->{$qual};
                if (!$path) {
                    # maybe package name used without import alias (same module)
                    for my $alias (keys %$imps) {
                        my $p = $imps->{$alias};
                        my $pn = $path_to_pkgname{$p} // basename($p);
                        if ($pn eq $qual) { $path = $p; last; }
                    }
                }
                next unless $path;
                my $key = "$path|$name";
                if (exists $decls{$key}) {
                    add_call($key, $file, $ln);
                } else {
                    # try method: path|Type.name - can't resolve type from qual call
                }
            }

            # unqualified function calls in same package
            if ($file =~ m{/internal/}) {
                my $pkg_path = pkg_path_from_file($file);
                while ($line =~ /(?<![A-Za-z0-9_\.])\b([A-Za-z_]\w*)\s*\(/g) {
                    my $name = $1;
                    next if $name =~ /^(if|for|switch|return|func|make|new|len|cap|append|delete|panic|recover|go|defer|map|struct|interface|select|range|case|default)$/;
                    my $key = "$pkg_path|$name";
                    add_call($key, $file, $ln) if exists $decls{$key};
                }
            } else {
                # file outside internal: unqualified won't hit internal private funcs
                # but could hit if same package - unlikely outside internal
            }

            # method calls: .MethodName(
            while ($line =~ /\.([A-Za-z_]\w*)\s*\(/g) {
                my $name = $1;
                next unless exists $name_to_keys{$name};
                for my $key (@{$name_to_keys{$name}}) {
                    next unless $decls{$key}{kind} eq 'method';
                    add_call($key, $file, $ln);
                }
            }
        }
    },
    no_chdir => 1,
}, $root);

# --- Phase 4: output top results ---
my @ranked = sort {
    (scalar(keys %{$call_sites{$b} // {}})) <=> (scalar(keys %{$call_sites{$a} // {}}))
    || $a cmp $b
} keys %decls;

print "TOP 25 by distinct call sites (all .go incl tests):\n";
for my $i (0..24) {
    last unless $i < @ranked;
    my $k = $ranked[$i];
    my $d = $decls{$k};
    my $n = scalar keys %{$call_sites{$k} // {}};
  printf "%4d  %s:%d  %s.%s (%s)\n", $n, $d->{file}, $d->{line}, $d->{pkg_name}, 
    ($d->{recv} ? "$d->{recv}." : '') . $d->{name}, $d->{kind};
}

# also compute excluding _test.go
print "\nTOP 25 excluding test files as call sites:\n";
my %call_sites_notest;
for my $k (keys %call_sites) {
    for my $site (keys %{$call_sites{$k}}) {
        next if $site =~ /_test\.go:/;
        $call_sites_notest{$k}{$site} = 1;
    }
}
@ranked = sort {
    (scalar(keys %{$call_sites_notest{$b} // {}})) <=> (scalar(keys %{$call_sites_notest{$a} // {}}))
} keys %decls;
for my $i (0..24) {
    last unless $i < @ranked;
    my $k = $ranked[$i];
    my $d = $decls{$k};
    my $n = scalar keys %{$call_sites_notest{$k} // {}};
  printf "%4d  %s:%d  %s.%s (%s)\n", $n, $d->{file}, $d->{line}, $d->{pkg_name},
    ($d->{recv} ? "$d->{recv}." : '') . $d->{name}, $d->{kind};
}

print "\nTotal declarations: " . scalar(keys %decls) . "\n";
PERL
