#!/usr/bin/perl
use strict;
use warnings;
use File::Basename;

my ($root, $module) = ('/bench/repo', 'github.com/usememos/memos');
my @go_files = map { chomp } `find '$root' -name '*.go' ! -path '*/vendor/*' 2>/dev/null`;

my (%file_pkg, %file_imports, %decls);

sub pkg_path {
    my ($f) = @_;
    $f =~ s{^\Q$root\E/}{};
    $f =~ s{/[^/]+$}{};
    return "$module/$f";
}

for my $file (@go_files) {
    open my $fh, '<', $file or next;
    my $content = do { local $/; <$fh> };
    close $fh;

    if ($content =~ /^package\s+(\w+)/m) {
        $file_pkg{$file} = $1;
    }

    my %imps;
    while ($content =~ /^import\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/mg) {
        my @lines = defined $2 ? qq{"$2"} : split /\n/, ($1 // '');
        for my $line (@lines) {
            next unless $line =~ /"([^"]+)"/;
            my $path = $1;
            my $alias = basename($path);
            $alias =~ s/-/_/g;
            if ($line =~ /^\s*(\w+)\s+"/) {
                $alias = $1;
            }
            $imps{$alias} = $path;
        }
    }
    $file_imports{$file} = \%imps;

    next unless $file =~ m{/internal/};

    my @lines = split /\n/, $content;
    for my $i (0 .. $#lines) {
        my $line = $lines[$i];
        next unless $line =~ /^func\s+(?:\(([^)]*)\)\s+)?([A-Za-z_]\w*)\s*\(/;
        my ($recv, $name) = ($1 // '', $2);
        next if $name =~ /^(Test|Benchmark|Example|Fuzz)/;
        next if $name eq 'init';

        my $recv_type = '';
        if ($recv =~ /\*?\s*([A-Za-z_]\w*)\s*$/) {
            $recv_type = $1;
        }

        my $pp = pkg_path($file);
        my $key = $recv_type ? "$pp|$recv_type.$name" : "$pp|$name";
        $decls{$key} = {
            file => $file,
            line => $i + 1,
            name => $name,
            recv => $recv_type,
            pp   => $pp,
            pn   => $file_pkg{$file},
            kind => ($recv_type ? 'method' : 'func'),
        };
    }
}

my %ppn;
for my $d (values %decls) {
    $ppn{$d->{pp}} = $d->{pn};
}

my (%sites_func_all, %sites_func_prod, %sites_all, %sites_prod);

sub add_site {
    my ($key, $file, $line, $bucket) = @_;
    return unless exists $decls{$key};

    my $d = $decls{$key};
    return if $file eq $d->{file} && $line == $d->{line};

    $sites_all{$key}{"$file:$line"} = 1;
    $sites_func_all{$key}{"$file:$line"} = 1 if $bucket eq 'func';

    unless ($file =~ /_test\.go$/) {
        $sites_prod{$key}{"$file:$line"} = 1;
        $sites_func_prod{$key}{"$file:$line"} = 1 if $bucket eq 'func';
    }
}

my @kw = qw(if for switch return func make new len cap append delete panic recover go defer map struct interface select range case default);

for my $file (@go_files) {
    open my $fh, '<', $file or next;
    my @lines = <$fh>;
    close $fh;

    my $imps = $file_imports{$file} // {};
    my $fpp  = ($file =~ m{/internal/}) ? pkg_path($file) : '';

    for my $i (0 .. $#lines) {
        my ($line, $ln) = ($lines[$i], $i + 1);
        next if $line =~ /^\s*func\s+/;

        while ($line =~ /\b([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
            my ($qual, $name) = ($1, $2);
            my $path = $imps->{$qual};
            if (!$path) {
                for my $alias (keys %$imps) {
                    my $pn = $ppn{$imps->{$alias}} // basename($imps->{$alias});
                    if ($pn eq $qual) {
                        $path = $imps->{$alias};
                        last;
                    }
                }
            }
            next unless $path;

            my $fk = "$path|$name";
            if (exists $decls{$fk} && $decls{$fk}{kind} eq 'func') {
                add_site($fk, $file, $ln, 'func');
            }

            for my $k (keys %decls) {
                next unless $decls{$k}{pp} eq $path;
                next unless $decls{$k}{name} eq $name;
                next unless $decls{$k}{kind} eq 'method';
                add_site($k, $file, $ln, 'meth');
            }
        }

        if ($fpp) {
            while ($line =~ /(?<![A-Za-z0-9_\.])\b([A-Za-z_]\w*)\s*\(/g) {
                my $name = $1;
                next if grep { $_ eq $name } @kw;
                my $key = "$fpp|$name";
                if (exists $decls{$key} && $decls{$key}{kind} eq 'func') {
                    add_site($key, $file, $ln, 'func');
                }
            }
        }
    }
}

sub print_top {
    my ($hash, $title, $limit, $kind_filter) = @_;
    print "$title\n";
    my @ranked = sort {
        (scalar(keys %{ $hash->{$b} // {} })) <=> (scalar(keys %{ $hash->{$a} // {} }))
    } keys %decls;

    my $shown = 0;
    for my $key (@ranked) {
        my $d = $decls{$key};
        next if defined $kind_filter && $d->{kind} ne $kind_filter;
        my $count = scalar keys %{ $hash->{$key} // {} };
        next unless $count > 0;

        my $sym = $d->{pn} . ($d->{recv} ? ".$d->{recv}." : '') . $d->{name};
        printf "%4d  %s:%d  %s (%s)\n", $count, $d->{file}, $d->{line}, $sym, $d->{kind};
        last if ++$shown >= $limit;
    }
    print "\n";
}

print "Total decls: " . scalar(keys %decls) . "\n\n";
print_top(\%sites_func_all, 'Package-level functions: all call sites', 25, 'func');
print_top(\%sites_func_prod, 'Package-level functions: prod-only call sites', 25, 'func');
print_top(\%sites_all, 'Funcs + import-qualified method calls: all', 25, undef);
print_top(\%sites_prod, 'Funcs + import-qualified method calls: prod-only', 25, undef);

